{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investment & Programs — {{BUSINESS_NAME}}</title>
  <meta name="description" content="A range of small-group and one-on-one aromatherapy gatherings and workshops that may support presence and intention.">
  <style>
    :root{--bg:#fbfbfb;--ink:#122;--muted:#6b6b6b;--accent:#8aa29a;--glass:rgba(255,255,255,0.6);--card:#ffffff}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;color:var(--ink);background:var(--bg);-webkit-font-smoothing:antialiased}
    header{display:flex;align-items:center;justify-content:space-between;padding:1.1rem 1.5rem;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);position:sticky;top:0;backdrop-filter:blur(6px);z-index:40;border-bottom:1px solid rgba(0,0,0,0.03)}
    .brand{display:flex;gap:.6rem;align-items:center}
    .brand strong{font-size:1rem}
    nav a{color:var(--ink);text-decoration:none;margin-left:1rem;font-weight:600}
    .wrap{max-width:980px;margin:2rem auto;padding:0 1.25rem}
    .hero{display:grid;grid-template-columns:1fr;gap:1rem;background:linear-gradient(180deg, #fff, var(--bg));padding:2rem;border-radius:12px;position:relative;overflow:hidden}
    .hero .title{font-size:1.5rem;font-weight:700;margin:0}
    .hero p{margin:.5rem 0 1rem;color:var(--muted)}
    .actions{display:flex;gap:.75rem}
    .btn{background:var(--accent);color:#fff;padding:.65rem .9rem;border-radius:8px;text-decoration:none;font-weight:700;border:0;cursor:pointer}
    .btn.ghost{background:transparent;color:var(--ink);border:1px solid rgba(0,0,0,0.06)}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;margin-top:1rem}
    .card{background:var(--card);padding:1rem;border-radius:10px;border:1px solid rgba(0,0,0,0.04);box-shadow:0 6px 18px rgba(16,24,32,0.04)}
    .card h3{margin:0 0 .5rem;font-size:1.05rem}
    .price{font-weight:800;font-size:1.25rem;color:var(--ink)}
    .muted{color:var(--muted);font-size:.95rem}
    .note{font-size:.9rem;color:var(--muted);margin-top:.5rem}
    .testimonials{margin-top:1.25rem}
    .faq{margin-top:1rem}
    footer{padding:2rem 0;text-align:center;color:var(--muted)}

    /* SVG pattern tucked into hero */
    .pattern-svg{position:absolute;right:-10%;top:-10%;width:48rem;opacity:.06;color:var(--accent);transform:rotate(10deg)}

    /* Reveal animation */
    .reveal{opacity:0;transform:translateY(18px);transition:opacity .7s ease,transform .7s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){
      .reveal{transition:none;opacity:1;transform:none}
    }

    /* Modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(8,10,12,0.45);display:flex;align-items:center;justify-content:center;z-index:60;opacity:0;pointer-events:none;transition:opacity .18s}
    .modal-backdrop.open{opacity:1;pointer-events:auto}
    .modal{background:#fff;border-radius:12px;max-width:680px;width:94%;padding:1.1rem;box-shadow:0 18px 42px rgba(10,14,18,0.28)}
    .modal .head{display:flex;align-items:center;justify-content:space-between}
    .modal .body{margin-top:.6rem}
    .circle{width:120px;height:120px;border-radius:50%;background:linear-gradient(135deg,var(--accent),#bcd4cf);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;margin:auto}
    .controls{display:flex;gap:.5rem;justify-content:center;margin-top:.75rem}
    .small{font-size:.9rem}

    /* Booking table */
    .booking{display:grid;grid-template-columns:1fr 320px;gap:1rem}
    form label{display:block;margin-top:.5rem;font-weight:700}
    input,select,textarea{width:100%;padding:.6rem;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:.25rem}

    @media (max-width:880px){.grid{grid-template-columns:1fr}.booking{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><circle cx="12" cy="12" r="10" fill="#8aa29a"/><path d="M7 12c1.5-3 5-4 8-3" stroke="#fff" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>{{BUSINESS_NAME}}</strong></div>
    <nav aria-label="Primary navigation">
      <a href="index.html">Gatherings</a>
      <a href="services.html">Offerings</a>
      <a href="blends.html">Blends</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Origins</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="hero">
      <svg class="pattern-svg" viewBox="0 0 600 400" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
        <defs>
          <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
            <rect width="40" height="40" fill="none"/>
            <circle cx="6" cy="6" r="2" fill="#7fa796"/>
            <circle cx="26" cy="26" r="2" fill="#7fa796"/>
          </pattern>
        </defs>
        <rect width="600" height="400" fill="url(#p)" />
      </svg>
      <div>
        <h1 class="title">Investment & program options that may support calm and focus</h1>
        <p class="muted">Choose from intimate circles, hands-on workshops, or focused consults — each approach is crafted to be safety-forward and practical.</p>
        <div class="actions">
          <button class="btn" id="tryNow">Try it now</button>
          <a class="btn ghost" href="book.html">Reserve a spot</a>
        </div>
      </div>
    </section>

    <section aria-labelledby="plans" class="reveal" id="plans">
      <h2 id="plans">Offerings & rates</h2>
      <p class="muted">Pricing framed as commitment levels — choose a tempo that suits your life.</p>
      <div class="grid" style="margin-top:1rem">
        <article class="card">
          <h3>Intro Circle — "First Light"</h3>
          <div class="price">$45 • single session</div>
          <p class="muted">60-minute small-group introduction to gentle aromatic practices. May support grounding and simple daily rituals.</p>
          <div class="note">Includes small blend sample. Group size: up to 8.</div>
        </article>
        <article class="card">
          <h3>Practice Series — "Four Evenings"</h3>
          <div class="price">$160 • 4-class series</div>
          <p class="muted">A short sequence focused on learning approachable practices to integrate into your week. May support mindful rhythm.</p>
          <div class="note">Each week centers a different approachable ritual; includes notes and dilution guidance.</div>
        </article>
        <article class="card">
          <h3>Focused Consult — "One-on-One"</h3>
          <div class="price">$120 • 75 mins</div>
          <p class="muted">Individual time to review scent safety, preferences, and create a simple at-home plan. Safety and patch-testing discussed.</p>
          <div class="note">Follow-up email with blend suggestions included.</div>
        </article>
      </div>
      <p class="note">Prices may vary by location. No medical claims are made; services are educational and supportive in nature.</p>
    </section>

    <section class="reveal" id="myth">
      <h2>Common questions & clarifications</h2>
      <p class="muted">A few clarifications many newcomers appreciate.</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1rem">
        <div class="card">
          <h3>Myth vs truth</h3>
          <p class="muted"><strong>Myth:</strong> Aromas are universally safe.
          <br/><strong>Truth:</strong> Individual sensitivity varies. We emphasize dilution, patch-testing, and avoiding contraindicated oils.</p>
        </div>
        <div class="card">
          <h3>How to prepare</h3>
          <p class="muted">Wear minimal fragrance, let us know about pregnancy or pets at home, and come with a notebook if you like.</p>
        </div>
      </div>
    </section>

    <section class="reveal testimonials">
      <h2>Notes from participants</h2>
      <div class="grid" style="margin-top:1rem">
        <div class="card"><strong>A.R.</strong><p class="muted">"A calm hour that gave me tools I could actually repeat at home."</p></div>
        <div class="card"><strong>S.J.</strong><p class="muted">"Clear instructions on dilution and how to test blends kept me safe and confident."</p></div>
        <div class="card"><strong>M.K.</strong><p class="muted">"I appreciated the small group — felt like a gentle reset."</p></div>
      </div>
    </section>

    <section class="reveal faq" id="faq">
      <h2>FAQ — Safety & practical notes</h2>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1rem">
        <div class="card">
          <h3>Dilution & patch test</h3>
          <p class="muted">We recommend dilute topical blends (commonly 1-3% for adults) and a small patch-test on the forearm when using a new oil. We discuss safe dilution in sessions.</p>
        </div>
        <div class="card">
          <h3>Pregnancy & medical conditions</h3>
          <p class="muted">Some oils are best avoided during pregnancy or with certain conditions. Please tell us about pregnancy, medication, or health concerns before a consult so we can adapt suggestions. No medical treatments are provided.</p>
        </div>
        <div class="card">
          <h3>Pets</h3>
          <p class="muted">Many essential oils can affect animals. We'll cover pet-safe options and diffusion practices to keep companions safe.</p>
        </div>
        <div class="card">
          <h3>Allergies & sensitivities</h3>
          <p class="muted">If you have known allergies, inform us and we will avoid those materials. Patch-testing is always encouraged.</p>
        </div>
      </div>
    </section>

    <section class="reveal" style="margin-top:1.25rem;padding:1rem;border-radius:10px;background:linear-gradient(180deg,#fff,var(--bg));border:1px solid rgba(0,0,0,0.03)">
      <h2>Ready to join a session?</h2>
      <p class="muted">Reserve a spot or book a consult. If you'd like a short guided moment now, use the Try it now button above.</p>
      <div style="display:flex;gap:.75rem;margin-top:.6rem">
        <a class="btn" href="book.html">Reserve now</a>
        <a class="btn ghost" href="contact.html">Ask a question</a>
      </div>
    </section>

    <footer class="reveal">
      <p class="muted">Questions? Call {{PHONE}} • Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <p class="muted">Serving {{CITY}}, {{STATE}}</p>
    </footer>
  </main>

  <!-- Modal: guided micro-practice -->
  <div class="modal-backdrop" id="modal" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle">
      <div class="head">
        <h3 id="modalTitle">Try a short guided practice</h3>
        <button id="closeModal" aria-label="Close" class="btn ghost">Close</button>
      </div>
      <div class="body">
        <p class="muted small">Choose a short practice below. This is a brief, non-medical exercise that may support presence.</p>
        <div style="display:flex;gap:.5rem;margin-top:.6rem;flex-wrap:wrap;justify-content:center">
          <button class="btn" data-practice="breath">Breathing (2 min)</button>
          <button class="btn" data-practice="journal">Journaling (5 prompts)</button>
          <button class="btn" data-practice="intent">Set an intention (1 min)</button>
        </div>

        <div id="exercise" style="margin-top:1rem"></div>
      </div>
    </div>
  </div>

  <script>
    // Scroll reveal
    (function(){
      var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var els = document.querySelectorAll('.reveal');
      if(prefersReduced){ els.forEach(function(e){ e.classList.add('visible'); }); return; }
      var io = new IntersectionObserver(function(entries){
        entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } });
      },{threshold:0.12});
      els.forEach(function(e){ io.observe(e); });
    })();

    // Modal behaviour and guided exercises
    (function(){
      var tryBtn = document.getElementById('tryNow');
      var modal = document.getElementById('modal');
      var close = document.getElementById('closeModal');
      var exercise = document.getElementById('exercise');
      var activeTimer = null;

      function open(){ modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); }
      function closeModal(){ modal.classList.remove('open'); modal.setAttribute('aria-hidden','true'); stopActive(); exercise.innerHTML=''; }
      function stopActive(){ if(activeTimer){ clearInterval(activeTimer); activeTimer=null; } }

      tryBtn.addEventListener('click',open);
      close.addEventListener('click',closeModal);
      modal.addEventListener('click',function(e){ if(e.target === modal) closeModal(); });

      document.querySelectorAll('#modal button[data-practice]').forEach(function(b){
        b.addEventListener('click',function(){
          var type = b.getAttribute('data-practice');
          startPractice(type);
        });
      });

      function startPractice(type){ stopActive(); exercise.innerHTML='';
        var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if(type==='breath'){
          // breathing 2-minute guided: 4-6-4 timing, repeat
          var total = 120; var started = 0; exercise.innerHTML = '<div class="circle" id="pulse">2:00</div><div class="controls"><button class="btn ghost" id="pause">Pause</button><button class="btn" id="stop">Stop</button></div>'; 
          var pulse = document.getElementById('pulse');
          var pauseFlag=false;
          document.getElementById('pause').addEventListener('click',function(){ pauseFlag=!pauseFlag; this.textContent = pauseFlag? 'Resume':'Pause'; });
          document.getElementById('stop').addEventListener('click',function(){ closeModal(); });
          if(prefersReduced){ // textual countdown
            activeTimer = setInterval(function(){ if(pauseFlag) return; started++; var left = Math.max(0,total-started); pulse.textContent = Math.floor(left/60)+':' + String(left%60).padStart(2,'0'); if(left===0){ clearInterval(activeTimer); activeTimer=null; pulse.textContent='Complete'; } },1000);
          } else {
            // animated circle breath cue
            pulse.style.transition='transform 1s ease';
            var cycle = 0; // cycle steps: inhale 4, hold 2, exhale 6 (duration scaled)
            var times = [4,2,6]; var phase = 0; var step = 0; var stepDur = 1000; // we'll tick each second
            pulse.textContent = 'Inhale';
            activeTimer = setInterval(function(){ if(pauseFlag) return; started++; var left = Math.max(0,total-started); var name = ['Inhale','Hold','Exhale'][phase]; pulse.textContent = name + ' — ' + (times[phase]-step) + 's';
              step++; if(step>=times[phase]){ phase=(phase+1)%3; step=0; }
              // simple scale animation
              if(name==='Inhale'){ pulse.style.transform='scale(1.18)'; }
              else if(name==='Hold'){ pulse.style.transform='scale(1.08)'; }
              else { pulse.style.transform='scale(0.86)'; }
              if(left===0){ clearInterval(activeTimer); activeTimer=null; pulse.textContent='Complete'; }
            },1000);
          }
        }
        if(type==='journal'){
          var prompts = ['Name three small steadying things you did this week.','Write one thing you want to let go of.','Describe a sensory moment you enjoyed recently.','Note a small action you can take tomorrow.','Close with a one-line intention.'];
          var idx=0; exercise.innerHTML = '<div><p class="muted" id="prompt">'+prompts[0]+'</p><textarea id="resp" rows="4" placeholder="Write here..." style="margin-top:.5rem"></textarea><div class="controls"><button class="btn ghost" id="next">Next</button><button class="btn" id="done">Done</button></div></div>';
          document.getElementById('next').addEventListener('click',function(){ idx++; if(idx>=prompts.length){ idx=prompts.length-1; } document.getElementById('prompt').textContent = prompts[idx]; document.getElementById('resp').value=''; });
          document.getElementById('done').addEventListener('click',function(){ closeModal(); });
        }
        if(type==='intent'){
          exercise.innerHTML = '<div style="text-align:center"><p class="muted">Take 60 seconds to set a clear, kind intention for your day.</p><div class="circle" id="timer">1:00</div><div class="controls"><button class="btn ghost" id="stop2">Close</button></div></div>';
          var left=60; document.getElementById('stop2').addEventListener('click',closeModal);
          activeTimer = setInterval(function(){ left--; var t = Math.floor(left/60)+":"+String(left%60).padStart(2,'0'); var el = document.getElementById('timer'); if(el) el.textContent = t; if(left<=0){ clearInterval(activeTimer); activeTimer=null; if(document.getElementById('timer')) document.getElementById('timer').textContent='Complete'; } },1000);
        }
      }

    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Origins & Approach — {{BUSINESS_NAME}}</title>
  <meta name="description" content="About our approach to thoughtful aromatherapy and small-group learning." />
  <style>
    :root{--bg:#fffdfb;--ink:#132;--muted:#69716a;--accent:#b09f8a}
    body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--ink);background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid rgba(0,0,0,0.04);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.6),transparent);backdrop-filter:blur(4px);z-index:30}
    nav a{margin-left:1rem;text-decoration:none;color:var(--ink);font-weight:700}
    .wrap{max-width:980px;margin:2rem auto;padding:0 1.25rem}
    .lead{display:grid;grid-template-columns:1fr 320px;gap:1rem;align-items:start}
    .card{background:#fff;padding:1rem;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    h1{margin:0 0 .4rem}
    .muted{color:var(--muted)}
    .pattern{width:100%;height:160px;border-radius:10px;overflow:hidden;margin-top:.9rem}
    .pattern svg{width:100%;height:100%;display:block}
    .timeline{margin-top:1rem}
    .timeline li{margin-bottom:.6rem}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .7s ease,transform .7s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media (max-width:880px){.lead{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:.6rem;align-items:center"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect width="24" height="24" rx="6" fill="#b09f8a"/><path d="M8 12c2-3 6-3 8-1" stroke="#fff" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>{{BUSINESS_NAME}}</strong></div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Investment</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="lead reveal">
      <div>
        <h1>Origins & method</h1>
        <p class="muted">An approachable practice rooted in attention to scent safety, gentle rituals, and accessible materials. We work in small groups and one-on-one sessions to help you adopt simple habits that may support steadiness.</p>

        <div style="display:flex;gap:.6rem;margin-top:1rem">
          <a class="btn" href="book.html" style="background:var(--accent);color:#fff;padding:.6rem .9rem;border-radius:8px;text-decoration:none;font-weight:700">Reserve a consult</a>
          <button id="tryNowAbout" style="padding:.6rem .9rem;border-radius:8px;border:1px solid rgba(0,0,0,0.06);background:transparent;cursor:pointer;font-weight:700">Try a brief practice</button>
        </div>
      </div>

      <aside class="card">
        <strong>Our focus</strong>
        <p class="muted" style="margin-top:.5rem">Practical guidance on scent safety, easy blends, and rituals you can repeat. No medical promises — just reliable, safety-forward education.</p>
        <div class="pattern" aria-hidden="true">
          <svg viewBox="0 0 400 160" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#f8f6f2"/><stop offset="1" stop-color="#f2efe9"/></linearGradient></defs><rect width="400" height="160" fill="url(#g)" /><g fill="#c9b69b" opacity="0.14"><circle cx="40" cy="40" r="18"/><circle cx="120" cy="110" r="20"/><circle cx="240" cy="60" r="14"/><circle cx="340" cy="120" r="12"/></g></svg>
        </div>
      </aside>
    </section>

    <section class="reveal timeline">
      <h2>How sessions are structured</h2>
      <ul>
        <li><strong>Welcome & safety window</strong>: We review any preferences, pregnancy notes, and pet considerations.</li>
        <li><strong>Scent introduction</strong>: Learning simple profiles and choosing materials to test.</li>
        <li><strong>Practice</strong>: Guided breathing or journaling with scent support (optional) to anchor the learning.</li>
        <li><strong>Takeaway</strong>: A short plan and dilution guidance you can use at home.</li>
      </ul>
    </section>

    <section class="reveal" style="margin-top:1rem">
      <h2>Our commitments</h2>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;">
        <div class="card"><strong>Safety-first</strong><p class="muted">Clear notes on dilution, patch testing, and choices around pregnancy and pets.</p></div>
        <div class="card"><strong>Practical</strong><p class="muted">Simple blends and small rituals you can repeat without special tools.</p></div>
      </div>
    </section>

    <section class="reveal" style="margin-top:1rem">
      <h2>People & practice notes</h2>
      <p class="muted">Sessions are led by trained facilitators who focus on client safety, clear instructions, and sensory-supported practices. We avoid grand claims and emphasize personal exploration.</p>
    </section>

    <section class="reveal" style="margin-top:1rem">
      <h2>FAQ — safety highlights</h2>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:.5rem">
        <div class="card"><h3>Patch testing</h3><p class="muted">We recommend a small arm patch test with new oils and discuss how to perform it safely in sessions.</p></div>
        <div class="card"><h3>Children & pets</h3><p class="muted">We adapt suggestions for households with pets and children; many oils require additional caution.</p></div>
      </div>
    </section>

    <footer class="reveal" style="margin-top:1.25rem;color:var(--muted)">
      <p>Contact: {{EMAIL}} • {{PHONE}} — Serving {{CITY}}, {{STATE}}</p>
    </footer>
  </main>

  <!-- Reuse the same modal script (simple) -->
  <div class="modal-backdrop" id="modalAbout" aria-hidden="true" style="display:none">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitleAbout">
      <div class="head"><h3 id="modalTitleAbout">Short guided practice</h3><button id="closeA" class="btn ghost">Close</button></div>
      <div class="body"><p class="muted small">A brief practice to center attention.</p><div id="aboutExercise"></div></div>
    </div>
  </div>

  <script>
    // Reveal animation
    (function(){
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ document.querySelectorAll('.reveal').forEach(function(e){ e.classList.add('visible'); }); return; }
      var io = new IntersectionObserver(function(entries){ entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('visible'); io.unobserve(en.target); } }); },{threshold:0.12});
      document.querySelectorAll('.reveal').forEach(function(e){ io.observe(e); });
    })();

    // Lightweight modal reuse
    (function(){
      var openBtn = document.getElementById('tryNowAbout');
      var modal = document.getElementById('modalAbout');
      var close = document.getElementById('closeA');
      function open(){ modal.style.display='flex'; modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); start(); }
      function closeModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stop(); }
