{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Reserve a spot in a small-group session or book a one-on-one consult."/>
  <style>
    :root{--bg:#f8fbfa;--ink:#122;--muted:#6a6f6a;--accent:#7ea79d}
    body{margin:0;font-family:system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--ink);background:var(--bg)}
    header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.2rem;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav a{margin-left:1rem;text-decoration:none;color:var(--ink);font-weight:700}
    .wrap{max-width:980px;margin:2rem auto;padding:0 1.25rem}
    h1{margin:0}
    .booking{display:grid;grid-template-columns:1fr 360px;gap:1rem}
    .card{background:#fff;padding:1rem;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    label{display:block;margin-top:.6rem;font-weight:700}
    input,select,textarea{width:100%;padding:.6rem;border-radius:8px;border:1px solid rgba(0,0,0,0.06);margin-top:.25rem}
    .btn{display:inline-block;padding:.6rem .9rem;border-radius:8px;background:var(--accent);color:#fff;border:0;font-weight:700;text-decoration:none}
    .note{color:var(--muted);font-size:.95rem}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .7s ease,transform .7s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}
    @media (max-width:920px){.booking{grid-template-columns:1fr}}
    .mini-calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-top:.5rem}
    .day{padding:.6rem;border-radius:8px;text-align:center;background:#f7f9f8}
    .day.available{background:linear-gradient(180deg,#fff,#eef6f3);cursor:pointer}
    .selected{box-shadow:0 8px 20px rgba(0,0,0,0.08);border:1px solid rgba(0,0,0,0.06)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:.6rem;align-items:center"><svg width="34" height="34" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><rect width="24" height="24" rx="6" fill="#7ea79d"/><path d="M8 12c2-3 6-3 8-1" stroke="#fff" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>{{BUSINESS_NAME}}</strong></div>
    <nav>
      <a href="index.html">Gatherings</a>
      <a href="services.html">Offerings</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Origins</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <section class="reveal">
      <h1>Reserve a session</h1>
      <p class="note">Choose a small-group or one-on-one consult. We will confirm availability and answer safety questions before the session.</p>
    </section>

    <section class="booking reveal">
      <div class="card">
        <form id="bookingForm">
          <label for="program">Select program</label>
          <select id="program" name="program">
            <option value="intro">Intro Circle — First Light ($45)</option>
            <option value="series">Practice Series — Four Evenings ($160)</option>
            <option value="consult">Focused Consult — One-on-One ($120)</option>
          </select>

          <label for="date">Pick a date</label>
          <div id="miniCal" class="mini-calendar" role="grid" aria-label="Available dates"></div>

          <label for="name">Your name</label>
          <input id="name" name="name" required placeholder="Full name" />

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required placeholder="you@example.com" />

          <label for="notes">Notes (pregnancy, pets, sensitivities)</label>
          <textarea id="notes" name="notes" rows="3" placeholder="If applicable, mention pregnancy, medications, pets, or known allergies"></textarea>

          <div style="display:flex;gap:.6rem;margin-top:1rem;align-items:center">
            <button class="btn" type="submit">Request booking</button>
            <a class="btn" id="quickTry" style="background:transparent;color:var(--ink);border:1px solid rgba(0,0,0,0.06);text-decoration:none">Quick practice</a>
          </div>
        </form>
        <p class="note" style="margin-top:.6rem">We follow a safety-first process: dilution guidance, patch test instructions, and pet considerations are discussed before using topical blends or home diffusion.</p>
      </div>

      <aside class="card">
        <strong>Booking summary</strong>
        <div style="margin-top:.6rem">
          <div id="summary" class="note">Select a program and date to see details here.</div>
        </div>
        <div style="margin-top:1rem">
          <strong>Need help?</strong>
          <p class="note">Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
        </div>
      </aside>
    </section>

    <footer class="reveal" style="margin-top:1rem;color:var(--muted)">
      <p>Serving {{CITY}}, {{STATE}}</p>
    </footer>
  </main>

  <!-- Lightweight guided practice modal for booking page -->
  <div class="modal-backdrop" id="modalBook" aria-hidden="true" style="display:none;align-items:center;justify-content:center;position:fixed;inset:0;background:rgba(0,0,0,0.36);z-index:60;">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="mbTitle" style="max-width:520px;width:90%;padding:1rem;border-radius:10px;background:#fff">
      <div class="head" style="display:flex;align-items:center;justify-content:space-between"><h3 id="mbTitle">Quick centering</h3><button id="closeBook" class="btn ghost">Close</button></div>
      <div class="body" style="margin-top:.6rem"><p class="muted">One minute breath and intention exercise. No claims, just a quiet pause.</p><div id="mbExercise" style="margin-top:.8rem"></div></div>
    </div>
  </div>

  <script>
    // Simple calendar mock: next 14 days, mark weekends unavailable, selectable others
    (function(){
      var cal = document.getElementById('miniCal');
      var today = new Date();
      var days = [];
      for(var i=0;i<14;i++){ var d = new Date(today.getFullYear(),today.getMonth(),today.getDate()+i); days.push(d); }
      days.forEach(function(d){ var day = document.createElement('div'); var wd = d.getDay(); var text = d.getDate(); day.className='day'+(wd===0||wd===6?'':' available'); day.textContent = new Intl.DateTimeFormat(undefined,{weekday:'short',day:'numeric'}).format(d); day.dataset.iso = d.toISOString().slice(0,10); if(day.classList.contains('available')){ day.addEventListener('click',function(){ document.querySelectorAll('.day').forEach(function(x){ x.classList.remove('selected'); }); this.classList.add('selected'); updateSummary(); }); } cal.appendChild(day); });

      function updateSummary(){ var program = document.getElementById('program').value; var date = document.querySelector('.day.selected'); var pText = {intro:'Intro Circle — $45',series:'Practice Series — $160',consult:'Focused Consult — $120'}[program]; var summary = document.getElementById('summary'); if(!date){ summary.textContent = 'Pick a date to reserve.'; } else { summary.innerHTML = '<div style="font-weight:700">'+pText+'</div><div class="note" style="margin-top:.35rem">Date: '+date.dataset.iso+'</div>'; } }
      document.getElementById('program').addEventListener('change',updateSummary);
    })();

    // Booking form submit (mock)
    document.getElementById('bookingForm').addEventListener('submit',function(e){ e.preventDefault(); var name = document.getElementById('name').value; var email = document.getElementById('email').value; var program = document.getElementById('program').value; var dateEl = document.querySelector('.day.selected'); if(!dateEl){ alert('Please choose a date from the calendar.'); return; } // Mock confirmation
      alert('Thanks, '+name+" — we've received your request for "+dateEl.dataset.iso+". We'll follow up at "+email+" with next steps and safety notes."); this.reset(); document.querySelectorAll('.day').forEach(function(x){ x.classList.remove('selected'); }); document.getElementById('summary').textContent='Select a program and date to see details here.';
    });

    // Modal quick practice for booking page
    (function(){
      var modal = document.getElementById('modalBook');
      var quick = document.getElementById('quickTry');
      var close = document.getElementById('closeBook');
      var ex = document.getElementById('mbExercise');
      var timerId=null;
      quick.addEventListener('click',function(e){ e.preventDefault(); open(); });
      close.addEventListener('click',closeModal);
      function open(){ modal.style.display='flex'; ex.innerHTML = '<div style="text-align:center"><div class="circle" style="width:96px;height:96px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--accent);color:#fff;font-weight:700">1:00</div><div style="margin-top:.6rem"><button id="mbStop" class="btn ghost">Stop</button></div></div>'; var left=60; timerId = setInterval(function(){ left--; var el = ex.querySelector('.circle'); if(el) el.textContent = Math.floor(left/60)+":"+String(left%60).padStart(2,'0'); if(left<=0){ clearInterval(timerId); timerId=null; if(el) el.textContent='Complete'; } },1000); }
      function closeModal(){ modal.style.display='none'; if(timerId) clearInterval(timerId); }
    })();

    // Respect reduced motion: remove animations by adding visible immediately
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){ document.querySelectorAll('.reveal').forEach(function(e){ e.classList.add('visible'); }); }
    else { document.querySelectorAll('.reveal').forEach(function(e){ setTimeout(function(){ e.classList.add('visible'); },120); }); }
  </script>
</body>
</html>"} 
